<?php declare(strict_types=1);namespace StudPulse\Bars;use StudPulse\Config;use StudPulse\Database\DB;use StudPulse\Domain\GroupRating;use StudPulse\Http\ApiError;use StudPulse\Integrations\MpeiSchedule;use StudPulse\Integrations\ScheduleSubgroups;use StudPulse\Security\{Auth,Crypto};final class BarsOfficialAdapter extends UnavailableAdapter{public function __construct(private Auth$auth,private?float$deadline=null){}public function capabilities():array{$map=parent::capabilities();foreach($map as&$capability){$capability=['status'=>CapabilityStatus::Unsupported->value,'reason'=>'Этот раздел ещё не подключён.'];}unset($capability);foreach(['identifyCurrentUser','getCurrentStudentProfile','getMyGroup','getMySchedule','getSubjects','getGradesAndAssessments','getRating','getAttendance','verifyAttendanceQr']as$method){$map[$method]=['status'=>CapabilityStatus::Supported->value];}return$map;}protected function blocked():never{throw new ApiError(503,'BLOCKED_EXTERNAL','Этот раздел БАРС ещё не подключён.');}private function credential():array{$row=DB::one("SELECT c.*,p.id AS connection FROM provider_credentials c JOIN provider_connections p ON p.id=c.connection_id WHERE p.user_id=? AND p.provider='bars' AND p.connection_status='connected' AND c.expires_at>UTC_TIMESTAMP(6)",[$this->auth->user['id']]);if(!$row){throw new ApiError(401,'BARS_LOGIN_REQUIRED','Для получения данных БАРС войдите заново.');}return[$row,json_decode(Crypto::decrypt($row['ciphertext']),true,32,JSON_THROW_ON_ERROR)];}public function identifyCurrentUser():ProviderResult{[,$data]=$this->credential();return new ProviderResult([['id'=>$data['profile']['id'],'name'=>$data['profile']['name']]],'БАРС МЭИ',$data['verifiedAt']??null);}public function getCurrentStudentProfile():ProviderResult{[,$data]=$this->credential();if(!isset($data['navigation'])){$this->sections();[,$data]=$this->credential();}$profile=$data['profile'];if(!empty($profile['course'])&&preg_match('/^(?:обучается|отчислен|зачислен|выпускник|акад