ttendance(string$term,bool$force=false):ProviderResult{$failure=null;try{$result=$this->section('attendance',$force);}catch(ApiError$error){if($error->status===401){throw$error;}$failure=$error;$result=new ProviderResult([],'БАРС МЭИ',null);}$blocks=$result->details['blocks']??[];$observed=$result->observedAt;$stale=$result->details['stale']??false;$parsed=BarsStatistics::attendance($blocks);if(!$parsed['summaryFromTotals']){try{$summary=$this->section('summary',$force);$attendance=BarsSections::attendanceBlocks($summary->details['blocks']??[]);if($attendance&&$attendance!==$blocks){$blocks=[...$attendance,...$blocks];$parsed=BarsStatistics::attendance($blocks);$observed??=$summary->observedAt;$stale=$stale||!empty($summary->details['stale']);}}catch(ApiError$error){if($error->status===401){throw$error;}$failure??=$error;}}if(!$parsed['summaryAvailable']&&!array_filter($blocks,static fn(array$block):bool=>$block['kind']==='table')&&$failure&&!in_array($failure->errorCode,['BARS_SECTION_UNAVAILABLE','BARS_ATTENDANCE_FORMAT'],true)){throw$failure;}return new ProviderResult($result->items,$result->source,$observed,false,[...$result->details,'blocks'=>$blocks,'attendance'=>$parsed,'stale'=>$stale,]);}public function verifiedJournal():?array{$period=BarsJournal::currentPeriod();$key='journal:access:v2:'.$period['academic_year'].':'.$period['season'];$entry=$this->read($key,function(BarsClient$client,array$state)use($period):array{if(($state['profile']['id']??null)!==($this->auth->user['external_subject']??'')){return[];}$code=trim($state['profile']['group']??'');$account=DB::one('SELECT login FROM bars_accounts WHERE user_id=? AND login_key=?',[$this->auth->user['id'],$state['loginKey']??'']);$login=$account['login']??'';if(!preg_match('/^[\p{L}\p{N} .\-‐‑–—]{2,40}$/uD',$code)||!preg_match('/^[a-zA-Z0-9._-]{1,100}$/D',$login)){return[];}return$client->journalAccess($code,$login,$period);});return$entry['value']?:null;}public function headmanJournal():array{$membership=$this->auth->journal();return$this->read('journal:roster:'.$membership['externalGroup'],static function(BarsClient$client)use($membership):array{return['url'=>$membership['url'],'items'=>$client->journalRoster($membership['externalGroup'])];})['value'];}public function sections():ProviderResult{[,$state]=$this->credential();if(!isset($state['navigation'])){try{$entry=$this->read('navigation',$this->loadNavigation(...));return$this->result($entry,BarsSections::catalog($this->sectionLinks($state,$entry['value']['links'])));}catch(ApiError$error){if($error->status<500){throw$error;}}}return new ProviderResult(BarsSections::catalog($this->sectionLinks($state,$state['navigation']??[])),'БАРС МЭИ',null,false,['navigationReady'=>isset($state['navigation'])]);}private function sectionLinks(array$state,array$links):array{$links['additional']='/bars_web/ST_AdEd/AdEdProgram/ListAdEdProgram?studentID='.rawurlencode($state['profile']['id']);if(!empty($state['loginKey'])){$links['surveys']=true;}return$links;}public function section(string$id,bool$force=false):ProviderResult{if($id==='grades'){return$this->getGradesAndAssessments('',$force);}if($id==='profile'){return$this->getCurrentStudentProfile();}if($id==='surveys'){[,$state]=$this->credential();$account=DB::one('SELECT login FROM bars_accounts WHERE user_id=? AND login_key=?',[$this->auth->user['id'],$state['loginKey']??'']);$login=$account['login']??'';if(!preg_match('/^[a-zA-Z0-9._-]{1,100}$/D',$login)){throw new ApiError(404,'BARS_SECTION_UNAVAILABLE','Для анкетирования нужен логин из профиля БАРС.');}$url='https://bars.mpei.ru/bars_web/US_Q/QuestionnaireAnswer/ListQuestionnaireAnswer?ac='.rawurlencode('public\\'.$login);return new ProviderResult([],'БАРС МЭИ',null,false,['externalUrl'=>$url]);}$entry=$this->read('section:v2:'.$id,function(BarsClient$client,array&$state)use($id,$force):array{if(!isset($state['navigation'])||($force&&in_array($id,['attendance','summary'],true)&&!isset($state['navigation'][$id])&&!isset($state['navigation']['summary']))){$state['studyCache']['navigation']=['at'=>time(),'value'=>$this->loadNavigation($client,$state)];}$links=$state['navigation'];$path=$this->sectionLinks($state,$links)[$id]??null;$summary=$id==='attendance'&&$path===null;if($summary){$path=$links['summary']??null;}if($path===null){if($id==='events'){$items=array_values(array_filter(BarsSections::catalog($links),static fn(array$item):bool=>$item['available']&&in_array($item['id'],['record-book','orders','scholarships','thanks'],true)));return['blocks'=>[],'sections'=>$items];}throw new ApiError(404,'BARS_SECTION_UNAVAILABLE','В меню открытого профиля БАРС нет ссылки на эту вкладку.');}$page=$client->section($path,$state['profile']['id']);$state['navigation']=array_replace($links,$page['links']);$blocks=$summary?BarsSections::attendanceBlocks($page['blocks']):$page['blocks'];if($summary&&!$blocks){throw new ApiError(502,'BARS_ATTENDANCE_FORMAT','В сводке БАРС не удалось прочитать таблицу посещаемости.');}return['blocks'=>$blocks,'ratings'=>str_starts_with($id,'rating-')?($page['ratings']??[]):[]];},$force);$value=$entry['value'];$details=['blocks'=>$value['blocks']];if(isset($value['sections'])){$details['sections']=$value['sections'];}return$this->result($entry,$value['ratings']??[],$details);}private function gradebook(bool$force=false):array{return$this->read('grades',$this->loadGradebook(...),$force);}private function loadNavigation(BarsClient$client,array&$state):array{$navigation=$client->navigation($state['profile']['id']);$state['navigation']=$navigation['links'];return$navigation;}private function loadGradebook(BarsClient$client,array&$state):array{$grades=$client->gradebook($state['profile']['id']);$state['navigation']=array_replace($state['navigation']??[],$grades['links']);unset($grades['links']);return$grades;}private function result(array$entry,array$items,array$details=[]):ProviderResult{if(!empty($entry['stale'])){$details['stale']=true;}return new ProviderResult($items,'БАРС МЭИ',gmdate('c',$entry['at']),false,$details);}public function withJournalClient(callable$fetch):array{$scope=$this->auth->journal(allowToken:true);return$this->read('journal:live',function(BarsClient$client,array$state)use($scope,$fetch):array{if(($state['profile']['id']??null)!==($this->auth->user['external_subject']??'')||trim($state['profile']['group']??'')!==$scope['code']){throw new ApiError(403,'BARS_JOURNAL_ACCESS','Открытый профиль БАРС изменился. Обновите страницу.');}return$fetch($client);},force:true,cache:false)['value'];}public function verifyAttendanceQr(#[\SensitiveParameter]string$raw):ProviderResult{$this->auth->browserOnly();$link=BarsQr::link($raw);[,$state]=$this->credential();$subject=$this->auth->user['external_subject']??'';if($subject===''||($state['profile']['id']??null)!==$subject){throw new ApiError(403,'BARS_PROFILE_SCOPE','Подключите собственный профиль БАРС.');}$client=new BarsClient($state['cookies'],$this->deadline);$client->registerAttendanceQr($link);return new ProviderResult([],'БАРС МЭИ',gmdate('c'),false,['confirmed'=>true]);}private function read(string$key,callable$fetch,bool$force=false,bool$cache=true):array{$result=DB::transaction(function()use($key,$fetch,$force,$cache):array|ApiError{$connection=DB::one("SELECT id FROM provider_connections WHERE user_id=? AND provider='bars' AND connection_status='connected' FOR UPDATE",[$this->auth->user['id']]);$credential=$connection?DB::one('SELECT * FROM provider_credentials WHERE connection_id=? AND expires_at>UTC_TIMESTAMP(6) FOR UPDATE',[$connection['id']]):null;if(!$credential){return new ApiError(401,'BARS_LOGIN_REQUIRED','Для получения данных БАРС войдите заново.');}$state=json_decode(Crypto::decrypt($credential['ciphertext']),true,32,JSON_THROW_ON_ERROR);$cached=$state['studyCache'][$key]??null;if(!$force&&$cached&&time()-$cached['at']<120){return$cached;}$client=new BarsClient($state['cookies'],$this->deadline);try{$value=$fetch($client,$state);$result=['at'=>time(),'valu